
const assets=[['Seedling installation','18 Jun','https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&w=700&q=80'],['Volunteers planting','22 Jun','https://images.unsplash.com/photo-1497250681960-ef046c08a56e?auto=format&fit=crop&w=700&q=80'],['Canopy follow-up','04 Jul','https://images.unsplash.com/photo-1473445361085-b9a07f55608b?auto=format&fit=crop&w=700&q=80']];const before='https://images.unsplash.com/photo-1501004318641-b39e6451bec6?auto=format&fit=crop&w=1000&q=80',after='https://images.unsplash.com/photo-1511497584788-876760111969?auto=format&fit=crop&w=1000&q=80';const qs=new URLSearchParams(location.search),variant=['triage','atlas','review'].includes(qs.get('variant'))?qs.get('variant'):'triage';const top=(section)=>`<header class="top"><div class="brand">IMPACT <b>MEDIA LAB</b></div><div class="eyebrow">${section} Â· Demo data</div><span class="btn primary" data-report>Generate report â†—</span></header>`;const photo=(a)=>`<img src="${a[2]}" alt="${a[0]}">`;function triage(){return `<div class="triage"><div class="shell">${top('Triage / upload queue')}<div class="triage-grid"><section class="card queue"><div class="eyebrow">01 / Intake</div><h2>Move media from unknown to useful.</h2><div class="upload"><strong>Drop field media here</strong><span class="muted">Images and video Â· Cloudinary keeps the original asset</span></div><div class="job"><div class="job-num">01</div><div><strong>North site Â· planting day</strong><small>12 assets Â· uploading</small><div class="progress"><i style="width:76%"></i></div></div><span class="status">76%</span></div><div class="job"><div class="job-num">02</div><div><strong>East plot Â· six-week follow-up</strong><small>8 assets Â· queued</small></div><span class="status">Queued</span></div><div class="job"><div class="job-num">03</div><div><strong>Oldest evidence Â· 2024 archive</strong><small>4 assets Â· needs review</small></div><span class="status" style="color:var(--orange)">Review</span></div></section><aside class="card summary"><div class="eyebrow" style="color:#8ea8ff">Live run</div><h2>Greener Noida</h2><p>AI processing stays visible while the team works.</p><div class="metric"><span>Assets ingested</span><b>24</b></div><div class="metric"><span>AI confidence</span><b>92%</b></div><div class="metric"><span>Source links</span><b>24/24</b></div><span class="btn">View project workspace</span></aside></div></div></div>`}function atlas(){return `<div class="atlas"><div class="shell">${top('Atlas / project map')}<div class="atlas-canvas"><div class="atlas-center"><div class="eyebrow" style="color:#8cdbc4">Project hub</div><h2>Greener Noida</h2><span class="pill">Tree plantation</span></div><div class="node n1"><strong>North site</strong><small>12 media Â· 3 moments</small></div><div class="node n2"><strong>East plot</strong><small>8 media Â· 2 moments</small></div><div class="node n3"><strong>18 Jun Â· Baseline</strong><small>Before evidence</small></div><div class="node n4"><strong>04 Jul Â· Follow-up</strong><small>Visible change</small></div><i class="connector c1"></i><i class="connector c2"></i><i class="connector c3"></i><i class="connector c4"></i><div class="atlas-legend"><i></i> Each node stays linked to source media</div></div><div class="atlas-stats"><div class="card"><b>24</b><span class="muted">linked assets</span></div><div class="card"><b>03</b><span class="muted">project locations</span></div><div class="card"><b>92%</b><span class="muted">confidence</span></div></div></div></div>`}
function review(){return `<div class="review"><div class="shell">${top('Review / evidence inspector')}<div class="review-grid"><section class="card review-canvas"><div class="eyebrow">Selected comparison</div><h2>Canopy follow-up</h2><div class="compare-big"><figure><img src="${before}" alt="Before"><span class="pill">Before Â· 18 Jun</span></figure><figure><img src="${after}" alt="After"><span class="pill">After Â· 04 Jul</span></figure></div><div class="filmstrip">${assets.map((a,i)=>`<figure class="frame ${i===2?'selected':''}">${photo(a)}<span>${a[1]} Â· demo</span></figure>`).join('')}</div></section><aside class="card inspector"><div class="eyebrow">Evidence inspector</div><h2>north-014.jpg</h2><span class="pill" style="background:#e8f5ef;color:var(--green)">Verified source</span><dl><div><dt>Project</dt><dd>Greener Noida</dd></div><div><dt>Location</dt><dd>Sector 98</dd></div><div><dt>Activity</dt><dd>Planting</dd></div><div><dt>Confidence</dt><dd>91%</dd></div></dl><div class="trace"><strong>Original asset</strong><span>cloudinary/media/north-014</span></div><div class="trace"><strong>AI transformation</strong><span>crop Â· color Â· scene tag</span></div><div class="trace"><strong>Used in report</strong><span>Section 02 Â· Visible change</span></div><span class="btn primary" style="margin-top:15px">Open source asset â†—</span></aside></div></div></div>`}function render(){document.body.className=variant;document.querySelector('#app').innerHTML=variant==='triage'?triage():variant==='atlas'?atlas():review();document.querySelectorAll('[data-report]').forEach(b=>b.addEventListener('click',()=>{b.textContent='Report ready âœ“';setTimeout(()=>b.textContent='Generate report â†—',1000)}))}document.querySelectorAll('.picker a').forEach(a=>a.classList.toggle('active',a.getAttribute('href').includes(variant)));render();

